"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["40434"],{52461(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_divulgacao.justificativa_obrigatoria","status":422,"titulo":"Publicar o nome integral exige justificativa"},"descricao":{"codigo":"uniplus.selecao.configuracao_divulgacao.justificativa_obrigatoria","requisitos":["UNI-REQ-0050"],"oQueAconteceu":["Ampliar a divulga\xe7\xe3o p\xfablica para o nome completo exige justificativa, que \xe9 congelada com a\\nconfigura\xe7\xe3o do processo. A lista `camposPublicos` inclui `NOME`, mas `justificativa` n\xe3o foi\\ninformada ou s\xf3 tem espa\xe7os em branco, que o sistema trata como aus\xeancia. O n\xfamero de inscri\xe7\xe3o\\ne o nome abreviado dispensam justificativa.","A recusa vem junto das demais viola\xe7\xf5es do mesmo pedido, no array `errors[]`. Como ela s\xf3 vale com\\na justificativa ausente, n\xe3o vem junto de\\n[`justificativa_muito_longa`](/erros/uniplus.selecao.configuracao_divulgacao.justificativa_muito_longa)\\nnem de\\n[`justificativa_caractere_invalido`](/erros/uniplus.selecao.configuracao_divulgacao.justificativa_caractere_invalido),\\nmas pode aparecer ao lado de\\n[`campo_nao_permitido`](/erros/uniplus.selecao.configuracao_divulgacao.campo_nao_permitido), de\\n[`numero_inscricao_obrigatorio`](/erros/uniplus.selecao.configuracao_divulgacao.numero_inscricao_obrigatorio)\\ne de\\n[`formas_de_identificacao_excludentes`](/erros/uniplus.selecao.configuracao_divulgacao.formas_de_identificacao_excludentes).","Esta mesma confer\xeancia \xe9 refeita quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada: em toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios,\\nas opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho da p\xe1gina).\\nPelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz o nome completo sem\\njustificativa, porque a defini\xe7\xe3o a recusa antes. Nessas leituras a recusa sai como viola\xe7\xe3o\\n\xfanica, sem a lista `errors[]`, e se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Escolha entre:","- informar `justificativa` com o motivo de divulgar o nome completo; ou\\n- tirar `NOME` da lista, ficando com `NOME_ABREVIADO`, que dispensa justificativa, ou s\xf3 com o\\n  `NUMERO_INSCRICAO`.","Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes de reenviar.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema\\nrecusou a configura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir a divulga\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o da divulga\xe7\xe3o p\xfablica do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Defini\xe7\xe3o de etapas e do cronograma das fases de processo publicado, quando declaram atos","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao divulgacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);